#[derive(Default)]
struct InMemoryUsers {
    users: RefCell<HashMap<UserId, User>>,
}
impl UserRepository for InMemoryUsers {
    fn save(&self, user: User) { self.users.borrow_mut().insert(user.id, user); }
    fn find(&self, id: UserId) -> Option<User> { self.users.borrow().get(&id).cloned() }
}
